/* Bench demos passcode gate — generated by publish-demos-site.sh, do not edit.
   Keeps honest people out; the body is already downloaded, so it is not real auth. */
(function(HASH,SALT){
"use strict";
var KEY = "bench-demos-gate", d = document, root = d.documentElement;
try { if (sessionStorage.getItem(KEY) === HASH) return; } catch (e) {}

/* hide the page until it is unlocked. visibility (not display) so the app underneath
   still lays out at the right size; the overlay opts back in to being visible. */
var st = d.createElement("style");
st.textContent =
  "html.bench-locked>body{visibility:hidden !important}" +
  "#bench-gate{visibility:visible !important;position:fixed;top:0;right:0;bottom:0;left:0;" +
    "z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:24px;" +
    "background:#14171c;color:#e6e8ea;font:16px/1.5 system-ui,-apple-system,'Segoe UI',sans-serif}" +
  "#bench-gate .box{width:100%;max-width:340px;text-align:center}" +
  "#bench-gate h1{font-size:20px;font-weight:600;margin:0 0 6px}" +
  "#bench-gate p{color:#9aa4b2;font-size:13.5px;margin:0 0 18px}" +
  "#bench-gate input{width:100%;padding:12px 14px;font-size:16px;text-align:center;" +
    "border-radius:10px;border:1px solid #2a3039;background:#1b1f26;color:#e6e8ea}" +
  "#bench-gate button{width:100%;margin-top:10px;padding:12px 14px;font-size:15px;font-weight:700;" +
    "border-radius:10px;border:1px solid #c9a24b;background:#c9a24b;color:#1b1e24;cursor:pointer}" +
  "#bench-gate .err{min-height:19px;margin-top:10px;font-size:13px;color:#d97b6a}";
root.className += " bench-locked";
(d.head || root).appendChild(st);

function hex(buf) {
  return Array.prototype.map.call(new Uint8Array(buf), function (b) {
    return ("0" + b.toString(16)).slice(-2);
  }).join("");
}

function build() {
  var g = d.createElement("div");
  g.id = "bench-gate";
  g.innerHTML = '<div class="box"><h1>Demos</h1><p>Enter the passcode you were given.</p>' +
    '<input id="bench-gate-in" type="password" autocapitalize="none" autocomplete="off" ' +
    'autocorrect="off" spellcheck="false" placeholder="passcode">' +
    '<button id="bench-gate-go" type="button">Enter</button>' +
    '<div class="err" id="bench-gate-err"></div></div>';
  d.body.appendChild(g);
  var input = d.getElementById("bench-gate-in"),
      err = d.getElementById("bench-gate-err");

  function unlock() {
    try { sessionStorage.setItem(KEY, HASH); } catch (e) {}
    root.className = root.className.replace(/\s*bench-locked\b/, "");
    if (g.parentNode) g.parentNode.removeChild(g);
    if (st.parentNode) st.parentNode.removeChild(st);
    /* canvas/Expo layouts that measured while hidden get a nudge to re-measure */
    try { dispatchEvent(new Event("resize")); } catch (e) {}
  }

  function submit() {
    var v = input.value;
    if (!v) return;
    var c = window.crypto;
    if (!c || !c.subtle || typeof TextEncoder !== "function") {
      err.textContent = "This browser cannot check the passcode — open the site over https.";
      return;
    }
    err.textContent = "checking…";
    c.subtle.digest("SHA-256", new TextEncoder().encode(SALT + ":" + v)).then(function (b) {
      if (hex(b) === HASH) { unlock(); return; }
      err.textContent = "Not that one. Try again.";
      input.value = "";
      input.focus();
    })["catch"](function () { err.textContent = "Could not check the passcode."; });
  }

  d.getElementById("bench-gate-go").addEventListener("click", submit);
  input.addEventListener("keydown", function (e) {
    if (e.key === "Enter" || e.keyCode === 13) submit();
  });
  setTimeout(function () { try { input.focus(); } catch (e) {} }, 60);
}

if (d.readyState === "loading") d.addEventListener("DOMContentLoaded", build);
else build();
})("ac65ca898f7d902b6804041fba85851562c8c6cb62b894f68cc71d786bb9619e","bench-demos");
